"One down!":"Біреуі кемідi!",
"Got him! Scrap metal.":"Жойдым! Бөлшектеліп кетті.",
"Another one for the scrapyard!":"Тағы біреуі сынықтарға!",
"Sparks flying!":"Ұшқындар шашырады!",
"I'm hit!":"Мені тиіп кетті!",
"Armor cracking!":"Сауыт сынып жатыр!",
"Ow! That was my favourite plate!":"Ой! Бұл менің сүйікті пластинам еді!",
"{name} is down!":"{name} жойылды!",
"We lost {name}!":"{name} жоғалттық!",
"{name}! No!":"{name}! Жоқ!",
