"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Кеннің жаңа көрінісі: кен тамырлары — қара базальттағы жарқыраған изумруд қырлы кристалдар, ұшқындар мен жасыл тұман; экстрактор — алтыбұрышты тұғыр, ұялы күмбез және жасыл шамшырағы бар торлы мұнара (жолақ пен жалау — команда түсі)",
"New in v6.1":"v6.1-дегі жаңалықтар",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Battlefield сияқты таңдаулы класс (U, өлгеннен кейін сандар): қолжетімді болса, сол класта қайта пайда боласың",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Техника бірінші тұлғадан (V — сырттан/кабинадан); жеңіл авто-мақсат алу — Баптауларда",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Өзектен шығу оңай: Бос орын — шахтаға, B — бетке капсула; қабілет әсерлері өлгенде тасталады",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Шексіз жетілу: генералдар мен Маршал ★, мансап деңгейлері, қару шеберлігі мен жабдықтары, медальдар, күнделікті келісімшарттар — «Мансап» экраны",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Стратегия: колесікпен тегіс масштабтау, юниттер үстіндегі белгішелер мен жазулар (Alt — барлығы), сол жақта «Әскер / Ғимараттар» панелі",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"Оң түйме — шабуылдай жылжу, екі рет оң түйме — жүріп бара атып марш; сирек бұйрықтар — «Қосымша бұйрықтар ▾» ішінде; түймелер қайталанбайды",
"New in v6":"v6-дағы жаңалықтар",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Шутер деңгейіндегі қару: лезде тиетін оқтар, минутына 720 оқ атар автомат, пулемет, серпін, оң түймемен көздеу, оқдәріліктер мен R қайта оқтау, тию белгілері",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Ауырырақ гравитация, жылдам жауап беретін ранец, Z немесе әуеде екі рет ранец арқылы серпіліс; басқа жауынгерге ауысқанда қару енді ілесіп ұшпайды",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Инженер-құрылысшылар: инженерді таңда, ғимаратты таңда, сызбаны қой; экстракторлар кен тамырларында; кіріс пен оны арттыру жолын көру үшін «КЕН» түймесін бас",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Сұр түймелерді басуға болады — себебін және шешімін көрсетеміз; ірі түймелер, «Орындалуда» жолағы, «▶ Идора», Tab — жалғыз режим пернесі",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Қарқынсыз және аунамайтын стратегия камерасы, меңзерге масштабтау, миникартаны сүйреуге болады",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Жаңа техника: «Шағол» рейдері, «Град» РСЗО (өздігінен бағыттайтын зымырандар), «Болға» миномёті; Галада «Занбур», «Кандӯ», «Манжаниқ»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Стратег бұйрықтарды үнемі өзгертпейді және дауыспен спамдамайды; шайқастар өзіңе келеді; B — қайта орналастыру, Shift+B — шайқасқа; компас, H — қай мақсат",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Еркін ойын (K) және жалғыз ойнау (J), F2 — пресеттер; Esc — үзіліс және жалғастыру; сақтаулар: слоттар, экспорт және импорт",
"New in v5.3":"v5.3-тегі жаңалықтар",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Ұшу: метеориттен алыста гравитация күшті, әуедегі C — тежегіш, тарту күші бағытты дәлірек бұрады; порталда енді тұрып қалмайсың",
"New in v5":"v5-тегі жаңалықтар",
"Endless war by default and battle scale: normal, large, epic":"Әдепкі бойынша шексіз соғыс және шайқас ауқымы: қалыпты, ірі, эпикалық",
"Save and load the battle (autosave every 3 minutes)":"Шайқасты сақтау және жүктеу (және әр 3 минут сайын автосақтау)",
"Squadmates with callsigns: portraits, health and live chatter":"Шақыру белгілері бар жауынгерлер: портреттер, денсаулық және тірі әңгімелер",
"Fog of war in strategy, friends and foes outlined differently":"Стратегиядағы соғыс тұманы, достар мен жаулар әртүрлі белгіленген",
"Camera fly-over when switching, portal aurora instead of rings":"Ауысқанда камераның ұшып өтуі, сақиналардың орнына портал шұғыласы",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Қосымша тапсырмалар, аспан арқылы қысқа жол, қорлары бар алғашқы экспедиция модульдері, кристалдар, кратерлердегі мұз, шаңды дауылдар",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Жаттығу, бейне жазатын кино-режим, стратегтен алып жүретін техника",
