"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Граната: {0} ұста — доға мен жарылыс шеңбері, жібер — лақтыру. Қашықтық — көру бұрышымен, дөңгелек — күш, оң жақ батырма — аяқ астына.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Гранаталар: G ұста — ұшу доғасы, жарылыс нүктесі мен шеңбері, қашықтық; жібер — лақтыру. Қашықтық көру бұрышына байланысты, дөңгелек — күш, оң жақ батырма — аяқ астына",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Граната серпіледі және беткейден домалайды, жарылыс 2.5 с кейін; 2 граната, қалпына келу 9 с; жақын жердегі жау гранатасы туралы ескерту белгісі",
