"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — ұста: доға мен жарылыс шеңбері көрінеді, жібер — лақтыру. Жарылыс 2.5 с кейін, 2 граната.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Граната ({0}): ұста — ұшу доғасы, жарылыс нүктесі мен шеңбері, қашықтық; жібер — лақтыру; қысқа басу — бірден лақтыру. Қашықтық — көру бұрышымен, дөңгелек — күш, оң жақ батырма — аяқ астына. Телефон: G ұстап, саусақты жүргіз.",
