"Builders are trained at the HQ — its panel is open on the right":"Инженерге штабтан тапсырыс беріледі — штаб панелі оң жақта ашық",
"pick a building → tap a spot → \"Build\"":"ғимаратты таңда → орынға түрт → «Салу»",
