"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"Консорциумның ауыр жауынгері (мылтықшы) енді сүйегі бар нағыз 3D-модель: тұрады, жүреді, қарумен жүгіреді, жүріп келе жатып атады және жойылғанда әдемі құлайды",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Модель метеорит бетіне нормаль бойынша тұрады, корпусын көздегішке қарай бұрады және пулеметті қолында ұстайды; алыста анимация сирек жаңарады — FPS түспейді",
"New in v6.5":"v6.5-тегі жаңалықтар",
"Barracks":"Казарма",
"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"Жаяу әскер: шабуылшы топтар, мылтықшылар, снайперлер, барлаушылар, капсулалар; сауыт пен қаруды жақсарту.",
"Ore depot":"Кен қоймасы",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"Инженерлер кристалдарды осында тапсырады. Кристалды алаңның жанына қой — қысқа жол, кен көп.",
"Tanks and vehicles. Requires Barracks.":"Танктер мен техника. Казарма қажет.",
"Autonomous combat drones. Requires Barracks.":"Автономды жауынгерлік дрондар. Казарма қажет.",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"Реактивті ранец II және Аспан десанты (ранецті элита). Мех зауыты қажет, 6:00-ден ашылады.",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"Өз нүктеңдегі екінші база: инженерлер, кристалдарды тапсыру, толықтыру.",
"Unlocks at {0}":"{0} кезінде ашылады",
