"Voice of hints & curator":"Кеңестер мен жетекші дауысы",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Телефон: стиктердің үш режимі. Тек сол жақ — «авто» (күшті магнит, бірақ оқ әлсіздеу). Тек оң жақ — нысана өзі қосылады, магнит күштірек, дәлдік жақсы. Екеуі бірге — нысанасыз, магнит пен дәлдік төмен. Оң жақтағы 👁 батырмасы интерфейсті жасырады/қайтарады.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Телефон: стратегия жеңілдетілген — тек құрылысшы мен ғимараттар. Сол жақта карточкалар (құрылысшы, штаб, казарма…): түрт — камера соған ұшады, төменде не салу/өндіру көрсетіледі. «Ұрысқа» — сол жақ жоғарыда. Әскер өзі соғысады. Толық стратегия — Баптаулар → Телефон.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Басқару — екі белгі: «Топтар» және «Техника» (телефонда техника әдепкіде өшірулі — оны ЖИ жүргізеді). Техника өшірулі болса, өз машинаңның жанында E (телефонда — оң жақтағы батырма) — оның мылтығына отыр: машина өзі жүреді, сен атасың. Ескі «сыныптардың жеке реті» — «Кеңейтілген» ішінде. Басқарған кезде бірлік рациямен жауап береді.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Ақылды кеңестер: негізгі кеңестер 2-ші іске қосудан кейін өзі сөнеді, бірақ ойын сен пайдаланбаған функцияны ескертеді. Белгілер: негізгі / күрделі / сирек, бөлек — кеңестер мен жетекші дауысы.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Рефлекс өлтірулерден зарядталады (серия — күштірек). Серіктестер артта қалса немесе өлсе — стратег саған жаңаларын десантпен түсіреді (әдеттегі толықтырудан қымбат). v7.2gfx графикасы мен дыбысы қосылды: будақ-будақ жарылыстар, түтін, сынықтар, шахта мен кратер акустикасы. Құрастыру күні енді нақты.",
