"Cinema: everything built":"Кино: бәрі салынған",
"both bases built and upgraded — for footage":"екі база да салынып, жетілдірілген — түсірілім үшін",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Кино режимі — сплитскрин: сол жақта бот-стратег (база мен әскерге үстінен көрініс), оң жақта бірінші жақтан бот-атқыш. Төмендегі батырмалар (және S, P пернелері): «Сплитскрин» және «★ Бәрі салынды» — екі база да түсірілім үшін салынып, жетілдірілген.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Өзек пен метеорит арқылы өтетін туннельдер жоқ — метеорит тұтас, шайқас тек бетінде өтеді.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Телефон: 👁 интерфейсті жасырады, бірақ ранецті, ⇆, стиктерді және міндет маркерін қалдырады. «◎ Көздеу» (тек оң саусақ) — магнит айтарлықтай күштірек әрі кеңірек; үш режимге арналған магнит күші — Баптаулар → Басқару → «Кеңейтілген». Көлік зеңбірегінде батырма «Түсу» деп аталады.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Жаттығу: телефонда — тек телефонға арналғандар, ДК-де — тек ДК-ге арналғандар. Барлық 4-еуі — «🛠 Әзірлеуші» мәзірінде. Әзірлеуші режимі мен Арсенал бір мәзірге біріктірілді (ұрыста — жоғарғы оң жақта «🛠 Мәзір», ДК-де қосымша F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"«Dendy (8 бит)» және «16 бит» графика стильдері: Баптаулар → Графика → «Графика стилі» (толығырақ — ⚙ батырмасы). Матчтың алғашқы ~10 с ішінде FPS 24-тен төмен болса, Dendy өздігінен қосылады (20-дан төмен болса — пиксель одан да ірі, 120 жол); жоғарыдағы «қалыпты қайтару» жазбасы қалыпты графиканы біржола қайтарады. Мәзірдегі өз таңдауың әрқашан маңыздырақ.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D орта модельдері (қирандылар, техника, бекіністер) — тек жақсы баға алғандары, талап бойынша интернеттен жүктеледі. Өшіру: Баптаулар → Графика → «Жаңа 3D орта модельдері».",
