"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Жауынгерлермен құрылыс: E (телефонда «Кіру») өз құрылысыңның жанында — жауынгер өзі салады, жақындағы серіктестер көмектеседі. Инженерлер бос болмаса, стратег өзі көмек сұрайды — «ҚҰРЫЛЫС» белгісі.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Стратег белгілері: стратег жақын маңдағы жау шоғырына ⌖ қояды — 8 с өткен соң сол жерді артиллерия соғады, ал жақындағы өз «Град» РСЗО-лары залп береді. Стратегия режимінен берген өз артиллериялық соққың да «Град» қолдауымен жүреді.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Жүк контейнерлеріндегі және құлаған спутниктердегі қару қоймалары (📦 70 м-ден көрінеді): E — 90 с-қа пулемет, тұтандырғыш оқтар немесе зымырандар, плюс толық гранаталар. Еңбектеу: Ctrl — жату / тұру (аласа, тыныш, дәлірек, бірақ баяу).",
"Anonymous statistics":"Анонимді статистика",
"no names or emails: version, device, play time — to make the game better":"аты-жөні мен поштасыз: нұсқа, құрылғы, ойын уақыты — ойынды жақсарту үшін",
"Anonymous statistics (no names or emails)":"Анонимді статистика (аты-жөні мен поштасыз)",
