"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Телефондағы стиктердің үш режимі, қарапайым стратегия, көлік зеңбірегі, шатқалды бедер, жасақ сыныптары, жарылғыш заттар",
"Lite mode, two-stick phone controls":"Жеңіл режим, телефондағы екі стик",
"Milestone: outposts and HQ upgrades, cinematic misses, knockdowns":"Негізгі нұсқа: форпосттар мен штабты жақсарту, киношылдық қателесулер, жарылыстан құлау",
