"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"«▶ Қазір ойнау» — мәзірдегі бірінші батырма: портал аспанымен қысқа ұшып өту — және бірден шайқас (өткізу — кез келген перне немесе түрту).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Тиген оқтар сезіледі: металл дыбыс пен ұшқындар, көздеу жанында өлтіру белгісі (басқа тисе — сары), ×N серия, жарылыстардан жұмсақ діріл, маңызды өлтірулерде слоу-мо. Дірілді, слоу-мо мен кеңесті Баптауларда өшіруге болады.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Матч қорытындысы: уақыт, жойылғандар, үздік серия, ★ MVP және үздік топ, матч карточкасы — «⇪ Бөлісу», PNG немесе ойынға сілтеме.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Ресурстардың астында сол жақта «қазір не істеу керек» кеңесі: стратег бұйрығы, басып алатын нүкте, Галаның шабуылы. ✕ немесе F7 — жию.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Қойындыны жапсаң немесе жисаң, шайқас өздігінен сақталады — мәзірде «⟲ Жалғастыру».",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 нұсқасы «🕘 Ойын нұсқасы» мәзірінде қалды — жаңасы ұнамаса. Анонимді статистика (аты-жөні мен поштасыз) енді жіберіледі; өшіру — Баптауларда.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"«Қазір ойнау», соққы кері байланысы, карточкалы матч қорытындысы, «не істеу керек» кеңесі, автосақтау",
"and older: v7.5, v7.4, milestones v1–v7.0":"және ескілері: v7.5, v7.4, v1–v7.0 белестері",
"New in v7.6":"v7.6-дағы жаңалықтар",
"NEW IN v7.6":"v7.6-ДАҒЫ ЖАҢАЛЫҚТАР",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Матч алдында фракция таңдау: «Консорсиум» (күштік сауытты ауыр жаяу әскер, сауыт пен артиллерия) немесе «Гала» (жылдамдық, дрондар тобыры, бұрмалайтын ауыр оқтар). AI екіншісімен ойнайды. Таңдау есте сақталады.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Әр фракцияның өз техникасы мен бірегей нәрсесі бар: Консорсиумда — «Мүйізтұмсық» танкі мен «Керамит плиталар», Галада — «Дрондар тобыры» мен «Фазалық ранецтер». Баланс бот матчтарымен тексерілген.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Жарылыс шұңқырлары: артиллерия, зымырандар мен танк зеңбіректері метеоритте шұңқыр қазады — олармен жүріп-тұруға болады, ішіне тығылуға да болады.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Жауынгерге 3-жақтан көрініс (V, есте сақталады; телефонда — Басқару) және зеңбірек қайда тиетінін көрсететін белгісі бар техниканың жұмсақ камерасы.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 нұсқасы «🕘 Ойын нұсқасы» мәзірінде қалды — жаңасы ұнамаса.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Матч алдында таңдауы бар Консорсиум / Гала фракциялары, жарылыс шұңқырлары, 3-жақтан көрініс",
