"Anomaly ahead":"Алда аномалия",
"dormant":"ұйқыда",
"Anomaly ahead! The vein is singing — go around!":"Алда аномалия! Тамыр ән салуда — айналып өтеміз!",
"Hear that hum? A singing vein. Keep clear!":"Гуілді естідіңдер ме? Әнші тамыр. Жақын бармаңдар!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Аномалия! Ауа айналып тұр — бұл құйын, айналып өт!",
"Rocks floating in the air… A whirlpool! Stay out!":"Тастар ауада ілініп тұр… Құйын! Жақындама!",
"Anomaly ahead — it is crackling with current!":"Алда аномалия — тоқпен сатырлап тұр!",
"Rods and lightning — a Crackler. It loves armour!":"Таяқшалар мен найзағай — Сатырлауық. Ол сауытты жақсы көреді!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Аномалия! Жер ыстықтан дірілдеп тұр — Алаукөз!",
"Careful, a Brazier underfoot!":"Абайла, аяқ астында Алаукөз!",
"Anomaly — green mist! Acid, hold your breath!":"Аномалия — жасыл тұман! Қышқыл, тыныстарыңды ұстаңдар!",
"The mist is drifting our way, go around!":"Тұман бізге қарай жылжып келеді, айналып өтеміз!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Аномалия! Ауа әйнектей — Линза, оқты бүгеді!",
"Everything is warping… a Lens nearby!":"Бәрі бұрмаланып тұр… жақын жерде Линза!",
"Ha! An enemy walked right into the anomaly!":"Ха! Жау аномалияның дәл ішіне кіріп кетті!",
"Got him! Lure them into anomalies!":"Түсті! Оларды аномалияларға тартыңдар!",
"Beautiful zap! One less tin can.":"Тамаша разряд! Бір консерв банкісі аз.",
"The anomaly got me!":"Мені аномалия соқты!",
"Ow! Don't go in there!":"Ой! Ол жаққа кірмеңдер!",
"Discharged! It is dormant now.":"Разрядтадым! Енді ол ұйқыда.",
"Clear, the anomaly is discharged.":"Таза, аномалия разрядталды.",
"They say veins hide artifacts. Only first the vein sings…":"Тамырларда артефакт жасырынады дейді. Тек алдымен тамыр ән салады…",
"Throw a bolt first, then walk. Old habit.":"Алдымен болт лақтыр, сосын жүр. Ескі әдет.",
