"Pause: resume, restart, training, graphics, settings, main menu":"Кідіріс: жалғастыру, қайта бастау, жаттығу, графика, баптаулар, басты мәзір",
"Menu: pause, restart, training, graphics, settings":"Мәзір: кідіріс, қайта бастау, жаттығу, графика, баптаулар",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Саусағыңды жерде ~0,3 с ұста — телефон діріл қағады, сары шеңбер шығады — содан кейін жібермей жүргіз: жақтау шығады. Немесе оң жақтағы «Жақтау» батырмасы. Топты жай түртуге де болады.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"iPhone-да толық экран үшін: «Бөлісу» ⬆ → «Басты экранға қосу» — ойын Safari панельдерінсіз ашылады.",
"Open portal-meteor.pages.dev for that.":"Ол үшін portal-meteor.pages.dev сайтын аш.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Түрту — таңдау · жерді түрту — бару · ұстап тұру — бұйрық мәзірі · ұстап жүргізу — жақтау · 2 саусақ — масштаб",
"Robo-ninja":"Робо-ниндзя",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Қастандықшы кейіпкер: телепорт-серпілістер, катана, сюрикендер. Жау аймақтарында өзі секіріп, роботтарды турайды. Бір жаққа 1.",
"Shadow protocol":"«Көлеңке» протоколы",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Зерттеу: Казармада робо-ниндзяны ашады. Дайын Мех зауыты қажет.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Кейіпкер (бір жаққа 1): жау аймақтарында өзі телепортталып, роботтарды турайды; қолмен ойнау үшін оған кіруге болады.",
"is ready. She works on her own (AUTO) — possess her to play manually":"дайын. Өзі жұмыс істейді (АВТО) — қолмен ойнау үшін басқарып көр",
