"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Қолмен: жауды түрту — серпіліс және соққы, сырғыту — сілтеу, 🛡 — блок",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Қолмен басқару: сол жақ батырма — катана, оң жақ батырма — блок, Shift — серпіліс, Q — сюрикендер, G — телепорт",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ниндзя: жауға түрту — серпіліс және соққы, оң жақта сырғыту — сілтеу, ● — соққы, 🛡 — блок (уақытында = парирлеу), ⇑ — серпіліс, ✦ — сюрикендер, ◎ — телепорт, АВТО — өзі",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ниндзя: сол жақ батырма — катана (ұстап тұр — ауыр соққы), оң жақ батырма — блок (уақытында = парирлеу), Shift/Z — серпіліс, Q — сюрикендер, G — көздеуішке телепорт, ауада секіру — қос секіру / қабырғамен жүгіру, {0} — АВТО",
