"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor радиосы: EDMITRY-дің 100+ трегі ойынның ішінде — 📻 батырмасы (ПК: 5 пернесі, [ ] — трек). Музыка желіден жүктеледі, ойынды ауырлатпайды; дыбыс деңгейі мен автоқосу баптауларда, «Spotify-да тыңдау» сілтемесі бар.",
