"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 оң жақта — Portal Meteor радиосы: ұрыс кезінде EDMITRY музыкасы.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Portal Meteor радиосы: ұрыс кезінде EDMITRY музыкасы. [ ] — трек.",
