"Radio: start by itself in battle":"Радио: ұрыста өзі қосылсын",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Робо-ниндзя: катанасы бар киборг. Казармада «Көлеңке» протоколы зерттеуімен ашылады (Мех зауыты қажет). Жау аймақтарына өзі телепортталады, жауларды бөліп кеседі (қансыз — ұшқындар), серпіледі, сюрикен лақтырады, жау ниндзясымен жекпе-жекке шығады. Оны басқар — АВТО режимі немесе қолмен басқару (телефонда — өз батырмалары).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor радиосы: EDMITRY-дің 103 трегі ойынның ішінде. 5 пернесі (қайта тағайындалады), телефонда — ☰ → Баптаулар → Дыбыс. Дыбыс деңгейі мен «ұрыста өзі қосылсын» — баптауларда; жарылыс кезінде және рация дауысы астында музыка бәсеңдейді.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Жаңа тілдер: өзбек және тәжік — толық; қытай, испан, португал — ішінара. Мәзірде «Жаңа матч» жанында жаңа тіл таңдау.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Телефон: «белгішелерді жасыру» 👁 қалған батырмаларды оң жақ шетте ұқыпты бағанға жинайды; портрет енді қабаттаспайды; iPhone — ойын Safari қимылдарымен қақтығыспайды, ал «Бөлісу → Басты экранға қосу» оны толық экранға ашады.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1-ден: бұрыштағы ☰ мәзірі (үзіліс, қайта бастау, жаттығу, графика), авто-Dendy жоқ, телефонда ✋ әрекет батырмасы. v7.8.1 және v7.8 «🕘 Ойын нұсқасы» мәзірінде қалды.",
