"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"Радиусы 12 м өрт аймағы 9 секунд жанады: уақыт бойынша зақым, басу, түтін. 2.5 с-тан кейін. Метанды тұтатады.",
