"Squad {0} is lost — its veterancy (lv {1}) is gone. See \"My squads → Fallen\".":"{0} тобы жоғалды — ардагерлік (дең. {1}) жойылды. Ол «Менің топтарым → Құлағандар» бөлімінде.",
