"Muffler":"Тыйғыш",
"Anomaly! Dust falling upwards — a Dislocation, it will pull you into the sky!":"Аномалия! Шаң жоғары құлап жатыр — Дислокация, аспанға тартады!",
"Dislocation ahead — step in and you come out on the other side of the meteor!":"Алда Дислокация — кім кірсе, метеориттің арғы жағына ұшып шығады!",
"Anomaly — the picture breaks into pixels! A Mosaic, aim goes wild!":"Аномалия — сурет пиксельге түсіп барады! Мозаика, нысана ұстамайды!",
"Pixel square — go around, everything jerks in there.":"Пиксельді шаршы — айналып өтеміз, ол жерде бәрі тартылады.",
"Frost on the ground — a coolant geyser! It will freeze you!":"Жердегі қырау — Салқындатқыш гейзері! Қатырып тастайды!",
"Hear the hiss? Geyser, back off!":"Ысқырықты естіп тұрсың ба? Гейзер, шегінеміз!",
"A strip of haze — a Draught, it blows even rockets away!":"Жолақ болып тұрған бу — Өтпе жел, зымырандарды да ұшырып әкетеді!",
"Draught ahead, hold on!":"Алда Өтпе жел, мықтап ұста!",
"Grey static — a Muffler! We lose the radio in there!":"Сұр статика — Тыйғыш! Ол жерде байланыс үзіледі!",
"Muffler ahead: no radio, no support.":"Алда Тыйғыш: байланыс та, қолдау да жоқ.",
