"Green grass hides infantry, sharp biome borders, the Dislocation throws you to the antipode, Verdans are neutral until provoked":"Жасыл шөп жаяу әскерді жасырады, биом шекаралары айқын, «Дислокация» антиподқа лақтырады, вердандар тиіспесең бейтарап",
"GRASS":"ШӨП",
