"Living world":"Тірі әлем",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Өзімдікілер көмек сұрап, сыйлық береді, қаһармандар квест береді, созылған майданды операциямен бұзады",
"A request":"Өзімдікілердің өтініші",
"Breakthrough":"Майдан бұзу",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Өзімдікілер кейде көмек сұрайды: радиодан дауыс, «ӨТІНІШ» карточкасы және ✋ белгісі. Топты қысып қалған — оның жанындағы жауларды жой. Сыйақы: базадан капсуламен жауынгер, багги жүгінен қару, мерген орны немесе орбитадан жабу. Қаламасаң — ✕ немесе жай елеме.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Ардагер барлаушы «Үкі» квест ұсынады. Y — қабылдау (N — бас тарту). ★ белгісіне бар, күзетті жой да ұшқыштың жанында 3 с тұр — ол сенің тобыңа қосылады.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Майдан тоқтады — штаб бұрылыс ұсынады. Y — қабылдау. Ретрансляторды маңайда жау жоқ күйде 8 с ұста: жау картасы 60 с көрінеді. Генератор — жау мұнаралары 2 мин үнсіз. Стратегте — «Топқа беру». Жау да солай жасай алады: ⚠ бақыла.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Өзімдікілер көмек сұрайды: «ӨТІНІШ» карточкасы және ✋ белгісі. Қысылған топтың жанындағы жауларды жой — сыйақы аласың. ✕ — өткізіп жіберу.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"«Үкі» қаһарманы квест ұсынады — «Қабылдау» түрт. ★ белгісіне бар, күзетті жой, ұшқыштың жанында тұр.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Майдан тоқтады — «Қабылдау» түрт те ретрансляторды 8 с ұста: жау картасы бір минутқа ашылады.",
