"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Базаның жүрегі: топтар, инженерлер, капсулалар, зерттеулер. Жоғалтсаң — жеңіліс.",
"Produces: ":"Шығарады: ",
"Launch pad":"Ұшыру алаңы",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Штаб жанындағы шахта: мұнан капсулалар, жабдықтау жәшіктері және бомбалаушылар аспан порталы арқылы нысанаға ұшады. Үстіне салуға болмайды.",
"Economy":"Экономика",
"Key building":"Негізгі ғимарат",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Әлсіз жері — арты (қозғалтқыш): зақым ×{0}. Зеңбірек, 2 пулемет мұнарашасы, зымыран кассетасы; өте баяу бұрылады — бүйірден айналып өтіңдер.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Әлсіз жері — құрсақ астындағы жарқыраған өзек: төменнен зақым ×{0}. Бұрмалау сәулесі және аймақтық тепкілеу; бөгеттерден аттап өтеді — қашықтық сақтаңдар, үйіліп тұрмаңдар.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Қарсы: авиабомбалар мен артиллерия (×{0}), зымырандар (×{1}), кілемдей бомбалау; оқтар дерлік пайдасыз (×{2}).",
"Faction":"Фракция",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Жылдам машиналар, дрон топтары, туннельдер және регенерация. Жаяу әскер жеңіл, бірақ жылдамырақ; зеңбіректер мен рельсалар күштірек соғады.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Күш сауытындағы ауыр жаяу әскер, бетон бөгеттері, жөндеу және артиллерия. Баяуырақ, бірақ берігірек.",
