"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Ойна да, дауыстап ойла: не түсініксіз, не ренжітеді, не ұнайды. Экран бұрышында нұсқа, уақыт және FPS көрінеді — олар арқылы жазба жазбалармен салыстырылады.",
